package com.example.petcarebook.service;
import com.example.petcarebook.entity.VaccinationRecord;
import com.example.petcarebook.entity.VaccineType;
import com.example.petcarebook.repository.PetRepository;
import com.example.petcarebook.repository.VaccinationRecordRepository;
import com.example.petcarebook.repository.VaccineTypeRepository;
import java.time.LocalDate;
import java.util.List;
import org.springframework.stereotype.Service;
@Service public class VaccinationRecordService { private final VaccinationRecordRepository repository; private final PetRepository petRepository; private final VaccineTypeRepository vaccineTypeRepository; public VaccinationRecordService(VaccinationRecordRepository repository, PetRepository petRepository, VaccineTypeRepository vaccineTypeRepository) { this.repository = repository; this.petRepository = petRepository; this.vaccineTypeRepository = vaccineTypeRepository; } public VaccinationRecord add(VaccinationRecord data) { if (!isValid(data)) return null; prepareDueDate(data); return repository.save(data); } public List<VaccinationRecord> getAll() { return repository.findAll(); } public VaccinationRecord getById(Long id) { return repository.findById(id).orElse(null); } public VaccinationRecord update(Long id, VaccinationRecord data) { VaccinationRecord record = getById(id); if (record == null || !isValid(data)) return null; record.setPetId(data.getPetId()); record.setVaccineTypeId(data.getVaccineTypeId()); record.setVaccineName(data.getVaccineName()); record.setDateGiven(data.getDateGiven()); prepareDueDate(record); return repository.save(record); } public boolean delete(Long id) { if (!repository.existsById(id)) return false; repository.deleteById(id); return true; } public List<VaccinationRecord> search(String keyword) { return repository.findByVaccineNameContainingIgnoreCase(keyword); } public List<VaccinationRecord> dueSoon(int days) { return repository.findByNextDueDateBetween(LocalDate.now(), LocalDate.now().plusDays(Math.max(0, days))); } private boolean isValid(VaccinationRecord data) { return !data.getDateGiven().isAfter(LocalDate.now()) && petRepository.existsById(data.getPetId()) && vaccineTypeRepository.existsById(data.getVaccineTypeId()); } private void prepareDueDate(VaccinationRecord data) { VaccineType type = vaccineTypeRepository.findById(data.getVaccineTypeId()).orElseThrow(); data.setNextDueDate(data.getDateGiven().plusDays(type.getIntervalDays())); } }
